let state;
function cleanText(v,max=150){return typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,max):''}
function cleanList(v,max=15){return Array.isArray(v)?v.slice(0,max).map(x=>cleanText(x,50)).filter(Boolean):[]}
function cleanId(v){return typeof v==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(v)?v:''}
function cleanDate(v){return typeof v==='string'&&Number.isFinite(Date.parse(v))?new Date(v).toISOString():dateFromNow(7)}
function hydrate(input){
 const base=makeSeed();if(!input||typeof input!=='object'||Array.isArray(input))return base;
 const old=input.user&&typeof input.user==='object'&&!Array.isArray(input.user)?input.user:{};
 const user={...base.user,first:cleanText(old.first,30)||base.user.first,last:cleanText(old.last,40)||base.user.last,grade:cleanText(old.grade,12)||base.user.grade,bio:cleanText(old.bio,250),skills:cleanList(old.skills),interests:cleanList(old.interests)};
 const validType=new Set(Object.keys(types)), validStatus=new Set(['PENDING','ACCEPTED','REJECTED','CANCELLED']);
 const opps=Array.isArray(input.opps)?input.opps.slice(0,150).filter(x=>x&&typeof x==='object'&&cleanId(x.id)).map(x=>({
  id:cleanId(x.id),type:validType.has(x.type)?x.type:'PROJECT',title:cleanText(x.title,75)||'Без названия',description:cleanText(x.description,800),creator:x.creator==='me'?'me':(demoPeople.some(p=>p.id===x.creator)?x.creator:'p1'),
  startsAt:cleanDate(x.startsAt),createdAt:cleanDate(x.createdAt),location:cleanText(x.location,80),max:Math.max(2,Math.min(500,Number(x.max)||20)),participants:Math.max(0,Math.min(500,Number(x.participants)||0)),skills:cleanList(x.skills),joinPolicy:x.joinPolicy==='OPEN'?'OPEN':'APPROVAL'
 })):base.opps;
 const ids=new Set(opps.map(o=>o.id));
 const applications=(Array.isArray(input.applications)?input.applications:[]).slice(0,400).filter(a=>a&&cleanId(a.id)&&ids.has(a.oppId)&&(a.personId==='me'||demoPeople.some(p=>p.id===a.personId))&&validStatus.has(a.status)).map(a=>({id:cleanId(a.id),oppId:a.oppId,personId:a.personId,status:a.status,createdAt:cleanDate(a.createdAt),message:cleanText(a.message,300)}));
 const notifications=(Array.isArray(input.notifications)?input.notifications:[]).slice(0,100).filter(n=>n&&cleanId(n.id)).map(n=>({id:cleanId(n.id),title:cleanText(n.title,80),text:cleanText(n.text,240),createdAt:cleanDate(n.createdAt),read:n.read===true}));
 const invites=(Array.isArray(input.invites)?input.invites:[]).slice(0,200).filter(i=>i&&cleanId(i.id)&&ids.has(i.oppId)&&demoPeople.some(p=>p.id===i.personId)).map(i=>({id:cleanId(i.id),oppId:i.oppId,personId:i.personId,createdAt:cleanDate(i.createdAt)}));
 const reports=(Array.isArray(input.reports)?input.reports:[]).slice(0,100).filter(r=>r&&cleanId(r.id)).map(r=>({id:cleanId(r.id),target:cleanText(r.target,100),reason:cleanText(r.reason,100),description:cleanText(r.description,600),createdAt:cleanDate(r.createdAt)}));
 return {...base,entered:input.entered===true,role:input.role==='organizer'?'organizer':'student',user,opps,applications,invites,notifications,reports,saved:cleanList(input.saved,150).filter(id=>ids.has(id)),likesPlus:input.likesPlus===true,prefs:{projects:input.prefs?.projects!==false,events:input.prefs?.events!==false,security:true}};
}
function load(){try{const raw=localStorage.getItem(STORAGE);if(raw&&raw.length<700000){state=hydrate(JSON.parse(raw));return;}}catch(e){console.warn('Повреждено локальное хранилище',e)}state=makeSeed();}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({...state,section:undefined,filter:undefined,sort:undefined,search:undefined,peopleSearch:undefined,skillFilter:undefined,mineTab:undefined}));}catch(e){console.warn('Не удалось сохранить',e);}}
function meName(){return `${state.user.first} ${state.user.last}`;}
function displayPerson(id){if(id==='me')return {...state.user,id:'me',tone:''};return demoPeople.find(x=>x.id===id)||{first:'Участник',last:'сообщества',grade:'',skills:[],interests:[],tone:''};}
function fullname(p){return `${p.first} ${p.last}`;}
function initials(p){return (p.first?.[0]||'?')+(p.last?.[0]||'');}
function avatar(p,cl=''){return `<div class="avatar ${esc(p.tone||'')} ${cl}">${esc(initials(p).toUpperCase())}</div>`;}
function joined(oppId,id='me'){return state.applications.find(x=>x.oppId===oppId&&x.personId===id&&x.status!=='CANCELLED'&&x.status!=='REJECTED');}
function notify(title,text){state.notifications.unshift({id:uid(),title,text,createdAt:new Date().toISOString(),read:false});persist();}
let modal=null,toastTimeout,scrollTopAfter=true;
function toast(msg){$('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=msg;document.body.append(t);clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.remove(),3100);}
