function chips(arr,max=3){return `<div class="chip-row">${(arr||[]).slice(0,max).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div>`;}
function oppCard(o){
 const owner=displayPerson(o.creator),curr=joined(o.id),saved=state.saved.includes(o.id);
 const kind=(types[o.type]||types.PROJECT);
 return `<article class="opp-card kind-${Object.keys(types).includes(o.type)?o.type.toLowerCase():'project'}">
 <div class="opp-cover"><div class="cover-orbit orbit-one"></div><div class="cover-orbit orbit-two"></div><span class="cover-corner-label">${esc(kind.label.toUpperCase())} / ${esc(CFG.demoSpace.toUpperCase())}</span><div class="cover-icon">${I(kind.icon)}</div><button class="save-button ${saved?'is-saved':''}" data-save="${esc(o.id)}" aria-label="${saved?'Удалить из сохранённого':'Сохранить'}" title="${saved?'Удалить из сохранённого':'Сохранить'}">${I('bookmark')}</button></div>
 <div class="opp-body"><div class="opp-header">${tag(o.type)}<span class="opp-date">${I('clock','ico-sm')} ${esc(dateLabel(o.startsAt))}</span></div>
 <h3>${esc(o.title)}</h3><p>${esc(truncate(o.description,120))}</p>${chips(o.skills,3)}
 <div class="opp-bottom"><div class="card-owner">${avatar(owner,'avatar-small')}<span><b>${esc(fullname(owner))}</b><small>${o.participants+state.applications.filter(a=>a.oppId===o.id&&a.status==='ACCEPTED').length} участников</small></span></div><button class="card-open" data-opp="${esc(o.id)}" aria-label="Открыть: ${esc(o.title)}">${I('arrow')}</button></div></div></article>`;
}
function createdByMe(){return state.opps.filter(o=>o.creator==='me');}
